)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_counts_as_unflagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5


def test_monitor_flag_rate_empty():
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_equal_groups():
    groups = {"a": [{"flagged": True}, {"flagged": False}], "b": [{"flagged": True}, {"flagged": False}]}
    assert pooled_flag_rate(groups) == 0.5


def test_pooled_flag_rate_weights_each_transcript_equally():
    groups = {"a": [{"flagged": True}], "b": [{"flagged": False}] * 3, "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0


@pytest.mark.parametrize(("days", "expected"), [(0, 0), (1, 4), (2, 6), (5, 7)])
def test_flags_in_window(days, expected):
    assert flags_in_window([1, 2, 4], days) == expected


def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]


def test_parse_transcript_log_skips_lines_and_strips_fields():
    lines = ["", " \t\n", "  # comment", " x1 , 3 , 0 ", " x2 , -1 , \n"]
    assert parse_transcript_log(lines) == [
        {"id": "x1", "day": 3, "flagged": False},
        {"id": "x2", "day": -1, "flagged": None},
    ]


@pytest.mark.parametrize("invalid_line", ["x,1", "x,1,0,extra", "x,not-a-day,0"])
def test_parse_transcript_log_errors_include_input_line_number(invalid_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_transcript_log(["", " # comment", "x,1,0", invalid_line])


def test_dedupe_transcripts_keeps_last_duplicate_and_sorts():
    events = parse_transcript_log(["b,9,1", "a,2,1", "c,1,0", "b,2,0"])
    assert dedupe_transcripts(events) == [events[2], events[1], events[3]]


def test_daily_flag_counts_includes_empty_days_and_ignores_outside_range():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,3,", "f,4,1", "g,5,1"])
    assert daily_flag_counts(events, 1, 4) == [2, 0, 0, 1]
    assert daily_flag_counts(events, 4, 1) == []


def test_monitor_summary_uses_pooled_rate_and_calendar_days():
    events = parse_transcript_log(["a,1,1", "b,4,1", "c,6,0"])
    groups = {"first": events[:2], "second": events[2:], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 3)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [{"flagged": True}], "empty": [], "b": [{"flagged": False}], "a": [{"flagged": True}]}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]


def test_flag_rate_by_group_includes_empty_groups_in_name_order():
    groups = {"z": [{"flagged": True}], "b": [], "a": [{"flagged": None}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 0.0), ("b", None), ("z", 1.0)]


